using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // EF 9 removed Cosmos DB indexing support (throws at runtime).
            // Indexing must be configured directly via Cosmos DB.

            // EF 9 changed the id property format from "EntityType|KeyValue" to
            // just "KeyValue". Preserve the old format for existing documents.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<BlogIdValueGenerator>();

            // EF 9 renamed the discriminator property from "Discriminator" to "$type".
            // Preserve the old property name so existing documents are still queryable.
            entity.HasDiscriminator<string>("Discriminator");
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Value generator that preserves the legacy "Discriminator|Key" id format.
}

using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
    {
        var key = entry.Property("Id").CurrentValue?.ToString()
            ?? Guid.NewGuid().ToString();
        return $"Blog|{key}";
    }
}

